index=faiss.IndexFlatL2(1536) # OpenAI로 임베딩 하면 1536차원
doc_embedding = np.array([get_embedding(doc) for doc in documents])
index.add(doc_embedding)  # 나온 숫자값을 백터DB에 넣는다.

# 사용자의 질문을 받아서 우리의 백터DB에 물어본다
def rag_query(user_query):
    query_embedding = get_embedding(user_query)
    print(query_embedding)
    _, indices = index.search(np.array([query_embedding]), k=1)   # 백터DB에서 질문 (user_query)의 숫자값과 가장 가까운거 k=1 개를 반환하시오.
    retrieved_doc = documents[indices[0][0]]

    prompt = f"""
    아래 내용을 보고 답변하시오. 아래 질문과 관련자료가 연관이 없거나, 답변할 수 없는 내용이면, 적절한 미사어구를 그때그때 다르게 붙여서 예의바르게 답변할 수 없다고 하시오. 그리고 적절한 이모티콘도 써서 답변하시오.

    사용자의 질문: {user_query}

    관련자료: {retrieved_doc}
    """

    print(">>>>>")
    print("우리가 실제로 gpt에게 물어보는 내용", prompt)
    print("<<<<<")

    """
    >>>>>
    우리가 실제로 gpt에게 물어보는 내용 
        아래 내용을 보고 답변하시오. 아래 질문과 관련자료가 연관이 없으면, 모른다고 답변하시오.

        사용자의 질문: 박수현은 언어가 쉽데요

        관련자료: Python은 개발 언어중에 가장 쉽다고 하는데, 그렇게 쉬운 언어는 아닙니다.
        
    <<<<<
    박수현이 언어가 쉽다고 말한 것과 관련하여, Python이 개발 언어 중에 가장 쉬운 언어로 알려져 있지만, 실제로 그렇게 쉬운 언어는 아니라는 점에서 언어의 난이도는 개인의 경험이나 배경에 따라 다르게 느껴질 수 있습니다. 언어의 난이도는 여러 요인에 따라 달라지므로, 박수현의 주장도 이해할 수 있습니다.
    """

    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {"role": "system", "content": "당신은 친절한 AI도우미 입니다."},
            {"role": "system", "content": prompt}
        ]
    )
    return response.choices[0].message.content

